// Extract and format both API results for GPT

// --- SUMMARY DATA ---
const summaryData = $('4a. WayinVideo — Get Summary Results').item.json.data;
const summary = summaryData.summary || '';
const highlights = Array.isArray(summaryData.highlights)
  ? summaryData.highlights.map((h, i) => `${i + 1}. ${h.desc}`).join('\n')
  : '';
const apiTags = Array.isArray(summaryData.tags) ? summaryData.tags : [];

// --- MOMENTS / CHAPTERS DATA ---
const clips = $('4b. WayinVideo — Get Moments Results').item.json.data?.clips || [];

// Sort chapters chronologically by start time
const sortedClips = clips.sort((a, b) => (a.begin_ms || 0) - (b.begin_ms || 0));

// Build formatted chapters list
const chapters = sortedClips.map((clip, index) => {
  const startMs = clip.begin_ms || 0;
  const mm = Math.floor(startMs / 60000);
  const ss = String(Math.floor((startMs % 60000) / 1000)).padStart(2, '0');
  const timestamp = `${mm}:${ss}`;
  return `${timestamp} ${clip.title || `Section ${index + 1}`}`;
});

// Make sure 0:00 Introduction is first
if (chapters.length > 0 && !chapters[0].startsWith('0:00')) {
  chapters.unshift('0:00 Introduction');
}

const chaptersText = chapters.join('\n');
const totalChapters = chapters.length;

// --- FORM DATA ---
const videoTitle = $('1. Form — Video URL + SEO Details').item.json['Video Title'];
const channelName = $('1. Form — Video URL + SEO Details').item.json['Channel Name'];
const niche = $('1. Form — Video URL + SEO Details').item.json['Content Niche'];
const focusKeyword = $('1. Form — Video URL + SEO Details').item.json['Focus Keyword'];
const channelLink = $('1. Form — Video URL + SEO Details').item.json['Channel / Website Link'] || '';
const videoUrl = $('1. Form — Video URL + SEO Details').item.json['YouTube Video URL'];

return [{
  json: {
    summary,
    highlights,
    apiTags,
    apiTagsText: apiTags.join(', '),
    chaptersText,
    totalChapters,
    videoTitle,
    channelName,
    niche,
    focusKeyword,
    channelLink,
    videoUrl
  }
}];

