// Parse AI YouTube SEO output
const output = $input.first().json.output || '';

// Extract each section
const descMatch = output.match(/YOUTUBE_DESCRIPTION:\s*([\s\S]*?)(?=\nCHAPTERS_STANDALONE:|$)/);
const chaptersMatch = output.match(/CHAPTERS_STANDALONE:\s*([\s\S]*?)(?=\nYOUTUBE_TAGS:|$)/);
const tagsMatch = output.match(/YOUTUBE_TAGS:\s*([\s\S]*?)(?=\nHASHTAGS:|$)/);
const hashtagsMatch = output.match(/HASHTAGS:\s*([\s\S]*?)(?=\nDESCRIPTION_HOOK:|$)/);
const hookMatch = output.match(/DESCRIPTION_HOOK:\s*([\s\S]*?)(?=\nSEO_NOTES:|$)/);
const seoNotesMatch = output.match(/SEO_NOTES:\s*([\s\S]*)$/);

const youtubeDescription = descMatch ? descMatch[1].trim() : '';
const chaptersStandalone = chaptersMatch ? chaptersMatch[1].trim() : '';
const youtubeTags = tagsMatch ? tagsMatch[1].trim() : '';
const hashtags = hashtagsMatch ? hashtagsMatch[1].trim() : '';
const descriptionHook = hookMatch ? hookMatch[1].trim() : '';
const seoNotes = seoNotesMatch ? seoNotesMatch[1].trim() : '';

if (!youtubeDescription || !youtubeTags) {
  throw new Error('Could not parse YouTube SEO output. Check AI prompt format.');
}

// Count tags
const tagCount = youtubeTags.split(',').map(t => t.trim()).filter(Boolean).length;
const descCharCount = youtubeDescription.length;

// Get metadata
const metaData = $('6. Code — Merge + Format API Results').item.json;

return [{
  json: {
    youtubeDescription,
    chaptersStandalone,
    youtubeTags,
    hashtags,
    descriptionHook,
    seoNotes,
    tagCount,
    descCharCount,
    focusKeyword: metaData.focusKeyword,
    videoTitle: metaData.videoTitle,
    channelName: metaData.channelName,
    niche: metaData.niche,
    videoUrl: metaData.videoUrl,
    totalChapters: metaData.totalChapters
  }
}];
